{
  "lines": {
    "food_first": [
      "看你饿着，我这有份{food}，先吃些。",
      "你似饿了，我带着{food}，要不用点。",
      "腹空难行，这份{food}你且拿去。"
    ],
    "food_again": [
      "又见面了，你仍饿着？这{food}给你。",
      "瞧你气色，怕是没吃，拿些{food}吧。",
      "你我又遇，这份{food}你收下垫垫。"
    ],
    "heal_first": [
      "伤得不轻，让我替你包扎一下。",
      "这伤得急，我先帮你裹上。",
      "你忍着些，我来给你包扎。"
    ],
    "heal_again": [
      "又碰上你，伤还重着，我来包扎。",
      "你伤未好，让我再替你裹一裹。",
      "看你这伤，先别动，我帮你包扎。"
    ]
  }
}

{
  "lines": {
    "guide_first": ["有个去处或许有用，可愿听我讲讲？", "我知晓一处可能帮得上忙，想听吗？", "有条路或许对你有益，愿不愿听？"],
    "guide_again": ["又见面了，新得的线索，可愿一听？", "先前见过，如今有条新消息，想听吗？", "咱们见过，我这有新门路，愿听否？"],
    "guide_gate": ["前日关外见过，怎么还在这儿？有门路可听？", "关外一别，你还未入城？有条路，愿听吗？", "前日关外相遇，现又在此，可愿听条门路？"],
    "guide_town": ["城里又遇，新得一线索，可愿听？", "先前见过，如今在城里，有新消息听吗？", "咱们见过，我这儿有条新门路，愿听否？"]
  }
}
